import fs from 'node:fs';
import { ContextRouter, discoverContextCandidates } from '@reactive-skills/runtime';
import { AxiError } from '../errors.js';
import { renderDetail, renderError, renderOutput } from '../toon.js';
const CONTEXT_ROUTE_USAGE = 'Usage: reactive-skills-axi context-route --message "..." [--candidates <JSON|@file>] [--token-budget <number>] [--json]';
const CONTEXT_CANDIDATES_GUIDANCE = 'Candidates must be a JSON array of skill metadata records shaped like {"id":"...","skill":"...","summary":"...","keywords":["..."]}, not arbitrary task labels or data. Each record describes one skill available to the agent.';
const CONTEXT_ROUTE_HELP = `${CONTEXT_ROUTE_USAGE}

Route the current task to one relevant skill and context slice.

--message <text>              Current user task or message.
--candidates <JSON|@file>     Optional skill choices. Omit to discover workspace and agent skill metadata.
                              Pass a JSON array of skill metadata records, not arbitrary task labels.
                              Each record requires id, skill, and summary; keywords are optional.
                              Pass [] to route with no candidates. All supplied skills are considered.
                              Large lists may require multiple Jev decisions.
--token-budget <number>       Maximum context tokens for selected route.
--json                        Print machine-readable JSON.

Example with automatic discovery:
  reactive-skills-axi context-route --message "Review this policy decision" --json

Example with an explicit skill list:
  reactive-skills-axi context-route --message "Review this policy decision" --candidates '[{"id":"policy-review","skill":"policy-review","summary":"Review decisions against policy","keywords":["policy"]}]' --json`;
function flagValue(args, flag) {
    const index = args.indexOf(flag);
    return index >= 0 ? args[index + 1] : undefined;
}
function parseJson(value, label) {
    if (value === undefined)
        return undefined;
    let source = value;
    try {
        if (value.startsWith('@'))
            source = fs.readFileSync(value.slice(1), 'utf8');
        return JSON.parse(source);
    }
    catch {
        throw new AxiError(`Invalid JSON ${label}`, 'VALIDATION_ERROR', [
            CONTEXT_ROUTE_USAGE,
            CONTEXT_CANDIDATES_GUIDANCE,
        ]);
    }
}
function isSkillCandidate(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value))
        return false;
    const candidate = value;
    return typeof candidate.id === 'string'
        && candidate.id.trim().length > 0
        && typeof candidate.skill === 'string'
        && candidate.skill.trim().length > 0
        && typeof candidate.summary === 'string'
        && candidate.summary.trim().length > 0
        && (candidate.keywords === undefined
            || (Array.isArray(candidate.keywords) && candidate.keywords.every((keyword) => typeof keyword === 'string')));
}
export async function contextRouteCommand(args = []) {
    if (args.includes('--help') || args.includes('-h'))
        return CONTEXT_ROUTE_HELP;
    const message = flagValue(args, '--message');
    if (!message) {
        return renderOutput([renderError('Missing message', 'VALIDATION_ERROR', [CONTEXT_ROUTE_USAGE])]);
    }
    const candidatesWereProvided = args.includes('--candidates');
    const candidatesValue = flagValue(args, '--candidates');
    let candidates;
    let stateHints;
    try {
        if (candidatesWereProvided) {
            if (!candidatesValue || candidatesValue.startsWith('--')) {
                return renderOutput([renderError('Missing --candidates value', 'VALIDATION_ERROR', [
                        CONTEXT_ROUTE_USAGE,
                        CONTEXT_CANDIDATES_GUIDANCE,
                    ])]);
            }
            const parsedCandidates = parseJson(candidatesValue, 'candidates');
            if (!Array.isArray(parsedCandidates)) {
                return renderOutput([renderError('Candidates must be a JSON array of skill metadata records', 'VALIDATION_ERROR', [
                        CONTEXT_CANDIDATES_GUIDANCE,
                    ])]);
            }
            const skillCandidates = parsedCandidates.filter(isSkillCandidate);
            if (skillCandidates.length !== parsedCandidates.length) {
                return renderOutput([renderError('Each candidate must describe one skill and include id, skill, and summary', 'VALIDATION_ERROR', [
                        CONTEXT_CANDIDATES_GUIDANCE,
                    ])]);
            }
            candidates = skillCandidates;
        }
        else {
            candidates = discoverContextCandidates(message, process.cwd());
        }
        stateHints = parseJson(flagValue(args, '--state-hints'), 'state hints');
    }
    catch (err) {
        const error = err instanceof AxiError
            ? err
            : new AxiError(err instanceof Error ? err.message : 'Context routing input is invalid', 'VALIDATION_ERROR');
        return renderOutput([renderError(error.message, error.code, error.suggestions)]);
    }
    const tokenBudgetRaw = flagValue(args, '--token-budget');
    const tokenBudget = tokenBudgetRaw ? Number(tokenBudgetRaw) : undefined;
    try {
        const decision = await new ContextRouter().route({
            userMessage: message,
            candidates,
            tokenBudget,
            stateHints,
        });
        if (args.includes('--json'))
            return JSON.stringify(decision, null, 2);
        return renderOutput([
            renderDetail('context_route', decision, [
                { type: 'field', key: 'route' },
                { type: 'field', key: 'skill' },
                { type: 'field', key: 'context_mode' },
                { type: 'field', key: 'context_budget_tokens' },
                { type: 'field', key: 'risk' },
                { type: 'field', key: 'confidence' },
                { type: 'field', key: 'adapter' },
            ]),
        ]);
    }
    catch (err) {
        const message = err instanceof Error ? err.message : 'Context routing failed';
        const invalidCandidateMetadata = message.startsWith('Each context route candidate needs')
            || message.startsWith('Duplicate context route candidate id:');
        const error = err instanceof AxiError
            ? err
            : new AxiError(message, invalidCandidateMetadata ? 'VALIDATION_ERROR' : 'RUNTIME_ERROR', invalidCandidateMetadata
                ? [CONTEXT_CANDIDATES_GUIDANCE]
                : ['Provide a non-empty message and bounded skill candidate metadata']);
        return renderOutput([renderError(error.message, error.code, error.suggestions)]);
    }
}
import fs from 'node:fs';
import { FSMEngine, JobManager, createSortableId } from '@reactive-skills/runtime';
import { AxiError } from '../errors.js';
import { renderError, renderHelp, renderOutput, renderDetail } from '../toon.js';
import { getSuggestions } from '../suggestions.js';
import { extractJobFlag, resolveSkillPath, resolveWorkspaceDir } from '../args.js';
function parsePayload(args) {
    let initialContext = {};
    const payloadIdx = args.indexOf('--payload');
    if (payloadIdx === -1)
        return initialContext;
    const payloadStr = args.slice(payloadIdx + 1).join(' ').trim();
    if (!payloadStr)
        return initialContext;
    if (payloadStr.startsWith('@') || fs.existsSync(payloadStr)) {
        const filePath = payloadStr.startsWith('@') ? payloadStr.slice(1) : payloadStr;
        try {
            initialContext = JSON.parse(fs.readFileSync(filePath, 'utf8'));
            return initialContext;
        }
        catch {
            return new AxiError('Invalid JSON payload file: ' + filePath, 'VALIDATION_ERROR', ['Usage: --payload \'{"key":"value"}\' or --payload @filepath.json']);
        }
    }
    try {
        initialContext = JSON.parse(payloadStr);
        return initialContext;
    }
    catch {
        return new AxiError('Invalid JSON payload', 'VALIDATION_ERROR', ['Usage: --payload \'{"key":"value"}\' or --payload @filepath.json']);
    }
}
export async function invokeCommand(args) {
    const { jobId, parentJobId, filteredArgs } = extractJobFlag(args);
    const skillName = filteredArgs[0];
    if (!skillName) {
        const error = new AxiError('Missing skill name', 'VALIDATION_ERROR', ['Usage: reactive-skills-axi invoke <skill-name> [--job <job-id>] [--parent <job-id>] [--payload JSON]', 'Example: reactive-skills-axi invoke resume-customizer --job worksoft --parent baseline --payload \'{"company_name":"Worksoft"}\'']);
        return renderOutput([
            renderError(error.message, error.code, error.suggestions),
        ]);
    }
    const parsedPayload = parsePayload(filteredArgs);
    if (parsedPayload instanceof AxiError) {
        return renderOutput([renderError(parsedPayload.message, parsedPayload.code, parsedPayload.suggestions)]);
    }
    try {
        const skillPath = resolveSkillPath(skillName);
        if (!skillPath) {
            const error = new AxiError(`Skill '${skillName}' not found in any known location`, 'NOT_FOUND', ['Checked: ./skills/, ~/.agents/skills/, ~/.gemini/config/skills/']);
            return renderOutput([renderError(error.message, error.code, error.suggestions)]);
        }
        const workspaceDir = resolveWorkspaceDir(skillPath);
        const jobManager = new JobManager(workspaceDir);
        const parentRunId = parentJobId
            ? (jobManager.resolveRunId(skillName, parentJobId) || undefined)
            : undefined;
        if (parentJobId && !parentRunId) {
            const error = new AxiError(`Parent job '${parentJobId}' not found for skill '${skillName}'`, 'VALIDATION_ERROR', [`Run \`reactive-skills-axi jobs ${skillName}\` to list available jobs.`]);
            return renderOutput([renderError(error.message, error.code, error.suggestions)]);
        }
        const existingRunId = jobId ? jobManager.resolveRunId(skillName, jobId) : null;
        if (existingRunId && parentRunId) {
            const existingJob = jobManager.getJob(skillName, existingRunId);
            if (existingJob?.parentRunId !== parentRunId) {
                const error = new AxiError(`Existing job '${jobId}' already has a different parent`, 'VALIDATION_ERROR', ['Start a new child job when changing the parent run.']);
                return renderOutput([renderError(error.message, error.code, error.suggestions)]);
            }
        }
        const runId = existingRunId || createSortableId();
        const engine = new FSMEngine({
            skillDir: skillPath,
            workspaceDir,
            jobId: runId,
            jobName: jobId || runId,
            setActive: !jobId,
            parentRunId,
            initialContext: parsedPayload,
            eventContext: { run_id: runId, parent_run_id: parentRunId },
        });
        try {
            const currentState = engine.getCurrentState();
            const promptSlice = engine.generatePromptSlice();
            const events = engine.getEventStore().getAll();
            const latestEvent = events.length > 0 ? events[events.length - 1] : undefined;
            const lines = [];
            lines.push(renderDetail('invoke', {
                skill_id: skillName,
                current_state: currentState,
                run_id: runId,
                event_id: latestEvent?.id || 'none',
            }, [
                { type: 'field', key: 'skill_id' },
                { type: 'field', key: 'current_state' },
                { type: 'field', key: 'run_id' },
                { type: 'field', key: 'event_id' },
            ]));
            lines.push(renderDetail('prompt', {
                raw_prompt: promptSlice.rawPrompt,
                allowed_tools: promptSlice.allowedTools.join(',') || 'none',
                exit_conditions: promptSlice.exitConditions.length,
            }, [
                { type: 'field', key: 'raw_prompt' },
                { type: 'field', key: 'allowed_tools' },
                { type: 'field', key: 'exit_conditions' },
            ]));
            const suggestions = getSuggestions({
                domain: 'invoke',
                action: 'call',
                skillName,
                jobId: runId,
                currentState,
            });
            lines.push(renderHelp(suggestions));
            return renderOutput(lines);
        }
        finally {
            engine.close?.();
        }
    }
    catch (err) {
        const error = err instanceof AxiError
            ? err
            : new AxiError(err instanceof Error ? err.message : 'Failed to invoke skill', 'NOT_FOUND', ['Check the skill name and ensure it exists in skills/ or global registry', 'Usage: reactive-skills-axi invoke <skill-name-or-path>']);
        return renderOutput([
            renderError(error.message, error.code, error.suggestions),
        ]);
    }
}
